package com.bank.dashboard;

import java.util.*;
import java.util.logging.*;
import static java.util.Comparator.comparingDouble;
import static java.util.stream.Collectors.*;

public class PipelineDemo {
    private static final Logger log = Logger.getLogger("Dashboard");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT", 1000000, true),
            new Employee("Amit", "IT", 800000, true),
            new Employee("Ghost", "IT", 500000, false),   // inactive → excluded
            new Employee("Priya", "Sales", 900000, true));
        DashboardService service = new DashboardService();

        Map<String, List<EmployeeDto>> view = service.buildView(staff);
        view.forEach((dept, dtos) -> dtos.forEach(d ->
            log.info(() -> dept + " → " + d.name() + " (" + d.salary() + ")")));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final double salary;
    private final boolean active;
    Employee(String name, String department, double salary, boolean active) {
            this.name = name;
            this.department = department
            this.salary = salary
            this.active = active;
    }
    String getName() { return name; }
    String getDepartment() { return department; }
    double getSalary() { return salary; }
    boolean isActive() { return active; }
}

// ─── Would be in dto/EmployeeDto.java ───
record EmployeeDto(String name, double salary) {}

// ─── Would be in service/DashboardService.java ───
class DashboardService {
    Map<String, List<EmployeeDto>> buildView(List<Employee> staff) {
        return staff.stream()
            .filter(Employee::isActive)                          // active only
            .collect(groupingBy(Employee::getDepartment,          // group by dept
                TreeMap::new,                                     // dept keys sorted
                collectingAndThen(
                    mapping(e -> new EmployeeDto(e.getName(), e.getSalary()), toList()), // → DTO
                    list -> { list.sort(comparingDouble(EmployeeDto::salary).reversed());
                              return list; })));                  // salary desc per dept
    }
}
